<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>12 Week Summer Body Ready Meal Plan</title>
<link href="https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,700;1,400&family=DM+Sans:wght@300;400;500&display=swap" rel="stylesheet">
<style>
  :root {
    --cream: #FDF6EE;
    --blush: #F2C4B0;
    --sage: #A8B89A;
    --terracotta: #C8705A;
    --deep: #3B2F2F;
    --soft-brown: #8B6B5A;
    --mint: #C6D9C6;
    --gold: #D4A853;
  }

  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    font-family: 'DM Sans', sans-serif;
    background-color: var(--cream);
    color: var(--deep);
    min-height: 100vh;
  }

  /* HERO */
  .hero {
    background: linear-gradient(135deg, var(--blush) 0%, #E8B4A0 40%, var(--sage) 100%);
    padding: 60px 30px 50px;
    text-align: center;
    position: relative;
    overflow: hidden;
  }
  .hero::before {
    content: '';
    position: absolute;
    top: -40px; right: -40px;
    width: 200px; height: 200px;
    border-radius: 50%;
    background: rgba(255,255,255,0.15);
  }
  .hero::after {
    content: '';
    position: absolute;
    bottom: -60px; left: -20px;
    width: 160px; height: 160px;
    border-radius: 50%;
    background: rgba(255,255,255,0.1);
  }
  .hero-badge {
    display: inline-block;
    background: rgba(255,255,255,0.4);
    border: 1px solid rgba(255,255,255,0.6);
    border-radius: 30px;
    padding: 6px 18px;
    font-size: 11px;
    font-weight: 500;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: var(--deep);
    margin-bottom: 16px;
  }
  .hero h1 {
    font-family: 'Playfair Display', serif;
    font-size: 38px;
    font-weight: 700;
    color: var(--deep);
    line-height: 1.2;
    margin-bottom: 10px;
  }
  .hero h1 em {
    font-style: italic;
    color: #6B3D2E;
  }
  .hero p {
    font-size: 14px;
    color: rgba(59,47,47,0.75);
    max-width: 340px;
    margin: 0 auto 24px;
    line-height: 1.6;
  }
  .hero-stats {
    display: flex;
    justify-content: center;
    gap: 24px;
  }
  .stat {
    background: rgba(255,255,255,0.45);
    border-radius: 14px;
    padding: 12px 18px;
    text-align: center;
  }
  .stat-num {
    font-family: 'Playfair Display', serif;
    font-size: 22px;
    font-weight: 700;
    color: var(--terracotta);
    display: block;
  }
  .stat-label {
    font-size: 10px;
    letter-spacing: 1px;
    text-transform: uppercase;
    color: var(--soft-brown);
  }

  /* NAV TABS */
  .week-nav {
    background: white;
    padding: 14px 20px;
    display: flex;
    gap: 8px;
    overflow-x: auto;
    scrollbar-width: none;
    border-bottom: 2px solid var(--blush);
    position: sticky;
    top: 0;
    z-index: 100;
  }
  .week-nav::-webkit-scrollbar { display: none; }
  .week-btn {
    flex-shrink: 0;
    padding: 8px 14px;
    border-radius: 20px;
    border: 1.5px solid var(--blush);
    background: transparent;
